    public static void main(String[] args) {
        long n = nextInt64();
        long sum = 0;
        long i = 0;

        while (sum + i + 1 <= n) {
            sum += i;
            i++;
        }

        println(n - sum);
        writer.flush();
    }

    private static String next() {
        return scanner.next();
    }

    private static long nextInt64() {
        return Long.parseLong(next());
    }

    private static int nextInt() {
        return Integer.parseInt(next());
    }

    private static double nextFloat() {
        return Double.parseDouble(next());
    }

    private static void println(Object... values) {
        for (int i = 0; i < values.length; i++) {
            if (i > 0) writer.print(" ");
            writer.print(values[i]);
        }
        writer.println();
    }

    private static void print(Object... values) {
        for (Object value : values) {
            writer.print(value);
        }
    }

    private static void printf(String format, Object... values) {
        writer.printf(format, values);
    }

    private static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() {
            if (pointer >= length) {
                try {
                    length = input.read(buffer);
                    pointer = 0;
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        String next() {
            StringBuilder builder = new StringBuilder();
            int c;

            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));

            if (c == -1) {
                throw new NoSuchElementException();
            }

            while (c != -1 && !Character.isWhitespace(c)) {
                builder.append((char) c);
                c = read();
            }

            return builder.toString();
        }
    }
}

